//! Catalog types and data (`catalog-data.ts`). `data/catalog.json` is generated by
//! `web-game/tools/conformance/export-catalog.ts`; numbers change there, not here.

use std::sync::LazyLock;

use indexmap::IndexMap;
use serde::{Deserialize, Serialize};

use crate::models::resource::Qty;
use crate::models::terrain::TerrainKind;

pub type StorageClass = String;

#[derive(Serialize, Deserialize, Clone, Debug, PartialEq)]
pub struct Material {
    pub id: String,
    pub name: String,
    pub tier: String,
    pub cls: StorageClass,
    pub unit: String,
    /// Where it comes from (T0 only).
    pub src: String,
    #[serde(rename = "use")]
    pub usage: String,
}

#[derive(Serialize, Deserialize, Clone, Copy, Debug, PartialEq)]
pub struct AtanorSpec {
    pub level: u32,
    pub cycles: f64,
    pub area: f64,
    pub arms: f64,
}

#[derive(Serialize, Deserialize, Clone, Debug, PartialEq)]
#[serde(rename_all = "camelCase")]
pub struct RecipeData {
    pub id: String,
    pub building: String,
    pub inp: Qty,
    pub out: Qty,
    /// By-products that lower the main product's value.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub by: Option<Qty>,
    /// Value shares of co-products (instead of by-products).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub co: Option<Qty>,
    /// Minutes per batch; computed from `atanor` for Atanor recipes.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub time: Option<f64>,
    /// MW while running; computed from `atanor` for Atanor recipes.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub power: Option<f64>,
    /// The process that sets the material's base value (alternatives are `false`).
    pub primary: bool,
    /// Machine time is ship time (expeditions), priced at `ship_minute`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub ship_time: Option<bool>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub atanor: Option<AtanorSpec>,
}

#[derive(Serialize, Deserialize, Clone, Debug, PartialEq)]
pub struct StorageClassInfo {
    pub cls: StorageClass,
    pub building: String,
    pub cap: f64,
    pub unit: String,
    /// MW at any fill.
    pub base: f64,
    /// MW per 1000 units stored.
    pub per1000: f64,
    pub loss: String,
    /// Example materials for the parity column.
    pub ex: Vec<String>,
}

#[derive(Serialize, Deserialize, Clone, Debug, PartialEq)]
#[serde(rename_all = "camelCase")]
pub struct BuildingDef {
    pub id: String,
    pub name: String,
    /// I infrastructure, M storage, E energy, W extraction, P processing, F factories, L logistics, O orbit, V vehicles.
    pub cat: String,
    pub era: u8,
    /// Footprint in tiles ('1', '3', '7') or a placement note ('orbita').
    pub fp: String,
    #[serde(rename = "maxL")]
    pub max_l: u32,
    /// L1 cost before the era multiplier.
    pub c1: Qty,
    /// Materials added at level k (they keep doubling on later levels); keys are the levels as strings.
    pub ex: IndexMap<String, Qty>,
    /// MW at L1: positive produces, negative consumes.
    pub p1: f64,
    /// Power growth per level for producers (default `producer_power_growth`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub pg: Option<f64>,
    /// Crew at L1; negative = provides living space.
    pub crew: f64,
    /// Build time at L1 [min].
    pub t1: f64,
    /// Recipe it runs at L1.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub rec: Option<String>,
    /// Hand-set costs per level (HQ), bypassing the formula and the era multiplier.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub explicit: Option<Vec<Qty>>,
    #[serde(default, skip_serializing_if = "Option::is_none", rename = "explicitT")]
    pub explicit_t: Option<Vec<f64>>,
}

impl BuildingDef {
    /// Materials added at level `k` (`ex[k]`).
    pub fn extra_at(&self, k: u32) -> Option<&Qty> {
        self.ex.get(&k.to_string())
    }
}

/// What one terrain class does to building (`terrain-data.ts`, T8).
#[derive(Serialize, Deserialize, Clone, Debug, PartialEq)]
#[serde(rename_all = "camelCase")]
pub struct TerrainKindRule {
    /// Polish name for the UI and the BAD_TERRAIN detail.
    pub name: String,
    /// Whether a footprint may cover it (no: BAD_TERRAIN).
    pub buildable: bool,
    /// Construction materials in % of the catalog cost (unused when not buildable).
    pub cost_pct: u32,
    /// Construction time in % of the catalog time (unused when not buildable).
    pub time_pct: u32,
}

/// The rules of every class, in the order of the TS record (it is serialised to the client as is).
#[derive(Serialize, Deserialize, Clone, Debug, PartialEq)]
pub struct TerrainKindRules {
    pub grass: TerrainKindRule,
    pub forest: TerrainKindRule,
    pub rock: TerrainKindRule,
    pub snow: TerrainKindRule,
    pub water: TerrainKindRule,
}

impl TerrainKindRules {
    pub fn get(&self, kind: TerrainKind) -> &TerrainKindRule {
        match kind {
            TerrainKind::Grass => &self.grass,
            TerrainKind::Forest => &self.forest,
            TerrainKind::Rock => &self.rock,
            TerrainKind::Snow => &self.snow,
            TerrainKind::Water => &self.water,
        }
    }
}

/// Road of the ruined settlement: overrides the class of the tile (levelled ground, old foundations).
#[derive(Serialize, Deserialize, Clone, Debug, PartialEq)]
#[serde(rename_all = "camelCase")]
pub struct TerrainRoadRule {
    pub name: String,
    pub cost_pct: u32,
    pub time_pct: u32,
}

/// Terrain building rules (`TERRAIN_RULES`): data of the catalog, read by `Rules::terrain()`.
#[derive(Serialize, Deserialize, Clone, Debug, PartialEq)]
pub struct TerrainRules {
    pub kinds: TerrainKindRules,
    pub road: TerrainRoadRule,
}

#[derive(Serialize, Deserialize, Clone, Debug, PartialEq)]
#[serde(rename_all = "camelCase")]
pub struct Catalog {
    pub materials: Vec<Material>,
    pub recipes: Vec<RecipeData>,
    pub storage_classes: Vec<StorageClassInfo>,
    pub buildings: Vec<BuildingDef>,
    pub vehicles: Vec<BuildingDef>,
    pub era_names: Vec<String>,
    /// Fusion capsules per light year of starship travel.
    pub fuel_per_ly: Qty,
    pub starship_modules: IndexMap<String, Qty>,
    pub starship_upgrades: IndexMap<String, Qty>,
    /// What terrain does to building (T8): buildable classes, cost and time in %.
    pub terrain: TerrainRules,
}

static CATALOG_JSON: &str = include_str!("../../data/catalog.json");

static CATALOG: LazyLock<Catalog> = LazyLock::new(|| serde_json::from_str(CATALOG_JSON).expect("data/catalog.json is valid"));

/// The economy catalog, parsed once per process.
pub fn catalog() -> &'static Catalog {
    &CATALOG
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn holds_the_full_catalog() {
        let c = catalog();
        assert_eq!(c.materials.len(), 37);
        assert_eq!(c.buildings.len(), 45);
        assert_eq!(c.vehicles.len(), 10);
        assert_eq!(c.era_names.len(), 5);
        let hq = &c.buildings[0];
        assert_eq!(hq.id, "HQ");
        assert_eq!(hq.explicit_t.as_ref().unwrap()[2], 120.0);
        assert_eq!(c.buildings.iter().find(|b| b.id == "HAB").unwrap().extra_at(2).unwrap().get("STA"), Some(&10.0));
        assert!(!c.terrain.kinds.get(TerrainKind::Water).buildable);
        assert_eq!((c.terrain.kinds.forest.cost_pct, c.terrain.kinds.forest.time_pct), (110, 150));
        assert_eq!((c.terrain.road.cost_pct, c.terrain.road.time_pct), (85, 75));
    }
}
